options( show.error.messages=F, error = function () { cat( geterrmessage(), file=stderr() ); q( "no", 1, F ) } )

# we need that to not crash galaxy with an UTF8 error on German LC settings.
loc <- Sys.setlocale("LC_MESSAGES", "en_US.UTF-8")

id_type <- "${id_type}"
organism <- "${organism}"
output_cols <- "${output_cols}"
file_has_header <- ${file_has_header}
remove_dups <- ${remove_dups}

input <- read.table('$id_file', header=file_has_header, sep="\t", quote="")
ids <- as.character(input[, 1])

if(organism == "Hs"){
    suppressPackageStartupMessages(library(org.Hs.eg.db))
    db <- org.Hs.eg.db
} else if (organism == "Mm"){
    suppressPackageStartupMessages(library(org.Mm.eg.db))
    db <- org.Mm.eg.db
} else if (organism == "Dm"){
    suppressPackageStartupMessages(library(org.Dm.eg.db))
    db <- org.Dm.eg.db
} else if (organism == "Dr"){
    suppressPackageStartupMessages(library(org.Dr.eg.db))
    db <- org.Dr.eg.db
} else if (organism == "Rn"){
    suppressPackageStartupMessages(library(org.Rn.eg.db))
    db <- org.Rn.eg.db
} else if (organism == "At"){
    suppressPackageStartupMessages(library(org.At.tair.db))
    db <- org.At.tair.db
} else if (organism == "Gg"){
    suppressPackageStartupMessages(library(org.Gg.eg.db))
    db <- org.Gg.eg.db
} else if (organism == "Bt"){
    suppressPackageStartupMessages(library(org.Bt.eg.db))
    db <- org.Bt.eg.db
} else {
    cat(paste("Organism type not supported", organism))
}

cols <- unlist(strsplit(output_cols, ","))
result <- select(db, keys=ids, keytype=id_type, columns=cols)

if(remove_dups) {
    result <- result[!duplicated(result$${id_type}),]
}

write.table(result, file='$out_tab', sep="\t", row.names=FALSE, quote=FALSE)

library(ampvis2, quietly = TRUE)
data <- readRDS("$data")
data <- amp_mergereplicates(
    data,
    merge_var = "$merge_var",
    #if $round != ""
        round = "$round"
    #end if
)
saveRDS(data, "$ampvis")

    classes <- sapply(data\$metadata, class)
    data\$metadata[is.na(data\$metadata)] <- "NA" ##the comparison below fails if NA values are present, see https://stackoverflow.com/questions/7355187/error-in-if-while-condition-missing-value-where-true-false-needed
    for(name in names(data\$metadata)){
        ## check if it is the column containing the sample names
        ## the additional column in the ist file can the be used
        ## to filter SampleIDs from select inputs
        ## (check for character columns only .. since data in the column is otherwise converted to the corresponding type .. which fails)
        if(classes[[name]] == "character" && all(data\$metadata[[name]] == rownames(data\$metadata))){
            sample_names <- TRUE;
        }else{
            sample_names <- FALSE;
        }
        for(m in unique(data\$metadata[[name]])){
            write(paste(name, m, sample_names, classes[[name]], sep="\t"), file="$metadata_list_out", append=T);
        }
    }
